begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(19);
insert into public.clinics(id,name) values('d1000000-0000-4000-8000-000000000001','Synthetic History A');
insert into auth.users(id) values('d2000000-0000-4000-8000-000000000001'),('d2000000-0000-4000-8000-000000000002');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('d1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001','reception',true),('d1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000002','manager',true);
insert into public.inquiries(id,clinic_id,owner_user_id,display_name,source) values('d3000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001','Synthetic History','phone');
select set_config('request.jwt.claim.sub','d2000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
create function pg_temp.history() returns jsonb language sql as $$select public.inquiry_planned_action_history('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000001')$$;
select ok(not has_function_privilege('anon','public.inquiry_planned_action_history(uuid,uuid)','EXECUTE'),'anonymous execution denied');
select is((select enabled from private.intake_command_settings),false,'writes disabled');
set local role authenticated;
select is(jsonb_array_length(pg_temp.history()->'items'),0,'empty history readable with writes disabled');
select throws_ok($$select * from private.inquiry_planned_action_receipts$$,'42501',null,'receipt table stays private');
reset role;
insert into private.inquiry_planned_action_receipts(clinic_id,actor_id,inquiry_id,command,request_key,normalized_payload,receipt)
select 'd1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000002','d3000000-0000-4000-8000-000000000001','set_planned_action',gen_random_uuid(),'{}',jsonb_build_object('vocabulary_version',1,'previous_planned_action',null,'planned_action',null,'previous_revision',0,'revision',0,'changed',false,'recorded_at','2026-10-26T20:00:00.123456Z','event_version',1) from generate_series(1,51);
select is(jsonb_array_length(pg_temp.history()->'items'),0,'previous actor excluded before limit');
insert into private.inquiry_planned_action_receipts(clinic_id,actor_id,inquiry_id,command,request_key,normalized_payload,receipt)
select 'd1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000001','set_planned_action',('d4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'{}',jsonb_build_object('vocabulary_version',1,'previous_planned_action',null,'planned_action',null,'previous_revision',0,'revision',0,'changed',false,'recorded_at',case n when 1 then '2026-10-26T20:00:00.000001Z' else '2026-10-26T20:00:00.000002Z' end,'event_version',1) from generate_series(1,50)n;
set local role authenticated;
select is(jsonb_array_length(pg_temp.history()->'items'),50,'returns50');
select is((pg_temp.history()->>'truncated')::boolean,false,'exact50 is complete');
select is(pg_temp.history()->'items'->49->>'recorded_at','2026-10-26T20:00:00.000001Z','full microsecond ordering');
select is((select count(*)::int from jsonb_object_keys(pg_temp.history()->'items'->0)),8,'private receipt fields omitted');
reset role;
insert into private.inquiry_planned_action_receipts(clinic_id,actor_id,inquiry_id,command,request_key,normalized_payload,receipt) values('d1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000001','set_planned_action','d4000000-0000-4000-8000-000000000051','{}','{"vocabulary_version":1,"previous_planned_action":null,"planned_action":"review_inquiry","previous_revision":0,"revision":1,"changed":true,"recorded_at":"2026-10-26T21:00:00.000002+01:00","event_version":1}');
select is((pg_temp.history()->>'truncated')::boolean,true,'51 authorized receipts partial');
select is(pg_temp.history()->'items'->0->>'planned_action','review_inquiry','equivalent instant uses descending private key');
update public.inquiries set owner_user_id='d2000000-0000-4000-8000-000000000002' where id='d3000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.history()$$,'PT404',null,'former owner denied even privileged');
update public.inquiries set owner_user_id='d2000000-0000-4000-8000-000000000001' where id='d3000000-0000-4000-8000-000000000001';
select is(pg_temp.history()->'items'->0->>'planned_action','review_inquiry','A reassigned back sees A own newest outcome');
select is(jsonb_array_length(pg_temp.history()->'items'),50,'B receipts excluded after reassignment back');
select set_config('request.method','GET',true);
select throws_ok($$select pg_temp.history()$$,'22023',null,'direct RPC requires POST');
select set_config('request.method','POST',true);
select throws_ok($$select public.inquiry_planned_action_history('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000099')$$,'PT404',null,'missing target matches denied boundary');
update public.clinic_memberships set role='assistant' where user_id='d2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.history()$$,'42501',null,'assistant denied even privileged');
update public.clinic_memberships set role='reception',active=false where user_id='d2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.history()$$,'42501',null,'inactive owner denied');
select is((select count(*)::int from private.outbox_events where clinic_id='d1000000-0000-4000-8000-000000000001'),0,'history emits no events');
select * from finish();
rollback;
